def _show_message_box(parent, icon, title, text, buttons=QMessageBox.Ok):
    """统一的消息框显示函数，确保文字颜色清晰"""
    msg_box = QMessageBox(parent)
    msg_box.setIcon(icon)
    msg_box.setWindowTitle(title)
    msg_box.setText(text)
    msg_box.setStandardButtons(buttons)
    msg_box.setStyleSheet(f"""
        QMessageBox {{
            background-color: {Theme.BG_ELEVATED};
        }}
        QLabel {{
            color: {Theme.TEXT_PRIMARY};
            font-size: {Typography.SIZE_BASE}px;
        }}
        QPushButton {{
            background-color: {Theme.ACCENT_PRIMARY};
            color: {Theme.TEXT_ON_ACCENT};
            border: none;
            padding: 9px 20px;
            border-radius: {Spacing.BORDER_RADIUS_SM}px;
            min-width: 80px;
            font-weight: {Typography.WEIGHT_MEDIUM};
        }}
        QPushButton:hover {{
            background-color: {Theme.ACCENT_HOVER};
        }}
    """)
    return msg_box.exec_()

    # 删除空白行
    lines = text.split('\n')
    cleaned_lines = [line.strip() for line in lines if line.strip()]
    text = '\n'.join(cleaned_lines)
    # 将所有换行替换为空格（避免TTS断句问题）
    text = text.replace('\n', ' ')
    # 删除多余空格（多个空格合并为一个）
    text = re.sub(r'\s+', ' ', text)
    return text.strip()


# ── TTS 字数统计 ──────────────────────────────────────────
class TTSStats:
    """记录本次运行和历史累计的 TTS 提交字数"""

    def __init__(self):
        from .config import get_app_dir
        self._path = get_app_dir() / "tts_stats.json"
        self._session = 0
        self._total   = self._load_total()

    def _load_total(self) -> int:
        try:
            data = json.loads(self._path.read_text(encoding="utf-8"))
            return int(data.get("total", 0))
        except Exception:
            return 0

    def add(self, char_count: int):
        self._session += char_count
        self._total   += char_count
        try:
            self._path.write_text(
                json.dumps({"total": self._total}, ensure_ascii=False),
                encoding="utf-8"
            )
        except Exception:
            pass

    def reset_session(self):
        self._session = 0

    @property
    def session(self) -> int:
        return self._session

    @property
    def total(self) -> int:
        return self._total

